<?php
namespace App\Http\Controllers;use App\Models\Video;use App\Models\VideoPlaylist;use App\Models\VideoSeries;use App\Services\VideoPlayerService;use Illuminate\View\View;
class VideoLibraryController extends Controller{public function index():View{return view('videos.index',['videos'=>Video::where('is_published',true)->with(['category','series'])->latest('published_at')->paginate(24),'seriesList'=>VideoSeries::where('is_published',true)->withCount(['videos'=>fn($q)=>$q->where('is_published',true)])->get(),'playlists'=>VideoPlaylist::where('is_published',true)->with(['videos'=>fn($q)=>$q->where('is_published',true)])->get()]);}public function show(Video $video,VideoPlayerService $player):View{abort_unless($video->is_published,404);return view('videos.show',compact('video','player'));}}
